ALTER TABLE "roles" ADD COLUMN "unrestricted" BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE "roles" SET "unrestricted" = TRUE WHERE "name" = 'admin';
ALTER TABLE "roles" ALTER COLUMN "unrestricted" DROP DEFAULT;
CREATE TABLE "role_permissions" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "role_id" BIGINT NOT NULL,
    "permission_id" BIGINT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_role_permissions_by_role_id" ON "role_permissions" ("role_id");
CREATE INDEX "index_role_permissions_by_permission_id" ON "role_permissions" ("permission_id");
CREATE TABLE "permissions" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "module" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_permissions_by_name" ON "permissions" ("name");
